<script lang="ts">
 import type {GameState} from '../lib/config/types';
 import PageHead from '../lib/components/PageHead.svelte';
 import ActionButton from '../lib/components/ActionButton.svelte';
 import {MODES,JOURNEY_THEMES,CARDS} from '../lib/domain/core.mjs';
 import {THEME_TASKS} from '../lib/domain/theme-tasks.mjs';
 import {taskBrief} from '../lib/domain/task-instructions.mjs';
 import PostageStamp from '../lib/components/PostageStamp.svelte';
 import Passport from '../lib/components/Passport.svelte';
 import type {Config,Mode,JourneyTheme,Place} from '../lib/config/types';
 import {onMount,untrack} from 'svelte';
 let {state:game}:{state:GameState}=$props();
 let form=$state<HTMLFormElement>();
 let choice=$state<Config>(untrack(()=>({...game.preferences})));
 const modeCopy={trial:{title:'先玩三张',time:'15–20 分钟',note:'零消费 · 不计分',icon:'✦'},short:{title:'轻轻走一会',time:'60–90 分钟',note:'4 张卡 · 一小段同行',icon:'↗'},half:{title:'留出半天',time:'3–4.5 小时',note:'7 张卡 · 慢慢探索',icon:'☀'},free:{title:'自由走走',time:'按你们的节奏',note:'随时抽卡 · 随时收尾',icon:'∞'}};
 const taskNames:Record<string,string>={scene:'探索',talk:'对话',event:'挑战'};
 let rewardsOpen=$state(false);
 let trial=$derived(choice.mode==='trial');
 let example=$derived(CARDS.find(card=>card.id===(trial?'scene-12':'scene-03'))!);
 let exampleBrief=$derived(taskBrief(example,{themePlan:trial||choice.journeyTheme==='mixed'?null:{tasks:THEME_TASKS[choice.journeyTheme]}}));
 let theme=$derived(JOURNEY_THEMES[trial?'mixed':choice.journeyTheme]);
 let sequence=$derived(MODES[choice.mode].sequence);
 function sync(){if(!form)return;const value=(name:string)=>form?.querySelector<HTMLInputElement|HTMLSelectElement>(`[name="${name}"]`)?.value;choice={...game.preferences,mode:(form.querySelector<HTMLInputElement>('[name=mode]:checked')?.value||game.preferences.mode) as Mode,journeyTheme:(form.querySelector<HTMLInputElement>('[name=journeyTheme]:checked')?.value||'mixed') as JourneyTheme,place:(value('place')||'both') as Place,budget:Number(value('budget')),scoring:!!form.querySelector<HTMLInputElement>('[name=scoring]')?.checked,rewards:[0,1,2].map(i=>value(`reward${i}`)||game.preferences.rewards[i])};}
 onMount(()=>queueMicrotask(sync));
</script>
<div class="page wide expedition-setup"><PageHead title={game.session?'还有一段散步没结束':'准备出发'}/>
 {#if game.session}<div class="resume-adventure"><Passport state={game}/><div class="panel"><h2>你们的冒险，随时可以接着走。</h2><p>继续上次的路线，或先结束这一局再重新出发。</p><ActionButton label="继续散步" action="nav" kind="block" attrs={{'data-route':'walk'}}/></div></div>
 {:else}
 <section class="expedition-intro"><div><p class="eyebrow">组队完成 / NEXT ADVENTURE</p><h2>把今天，<br>交给一点意外。</h2><p>一座城市，两位同行者。<br>选好节奏，剩下的交给下一张卡。</p></div><Passport state={game} config={choice}/></section>
 <form id="setup-form" bind:this={form} oninput={sync} onchange={sync} class="expedition-form">
  <div class="expedition-controls">
   <fieldset class="setup-section"><legend><span class="step-number">01</span>今天留多少时间？</legend><p class="section-help">走一小段，也可以是一场完整的冒险。</p><div class="trip-modes">{#each Object.entries(modeCopy) as [key,item]}<label class="trip-mode"><input type="radio" name="mode" value={key} checked={game.preferences.mode===key}><span class="mode-icon" aria-hidden="true">{item.icon}</span><strong>{item.title}</strong><span class="mode-time">{item.time}</span><span class="mode-note">{item.note}</span></label>{/each}</div></fieldset>
   <fieldset class="setup-section"><legend><span class="step-number">02</span>这一程想怎么玩？</legend><p class="section-help">{trial?'三卡试玩先发现街角，再一起选择线索或声音方向。':'选一种冒险的气质，任务会沿着这个方向展开。'}</p><div class:trial-themes={trial} class="theme-routes">{#each Object.entries(JOURNEY_THEMES) as [key,item]}<label class="theme-route"><input type="radio" name="journeyTheme" value={key} checked={game.preferences.journeyTheme===key} disabled={trial}><div class="route-stamp"><PostageStamp variant={key==='observe'?4:key==='duo'?5:3} compact/></div><span><strong>{item.name}</strong><span class="route-description">{item.opening}</span></span><span class="route-check" aria-hidden="true">✓</span></label>{/each}</div><section class="theme-example" aria-label="主题代表任务" data-theme-example><span class="small muted">比如这一张 · {trial?'三卡试玩':theme.name}</span><h3>{example.text}</h3><p>{exampleBrief.action}</p><p class="help">完成：{exampleBrief.done}</p></section><p class="help">{trial?'试玩固定为零消费、不计分。正式旅程再来挑选主题。':'想抽自己写的卡，选随心探索。主题卡池用完时，可以保留当前卡或跳过。'}</p></fieldset>
   <fieldset class="setup-section"><legend><span class="step-number">03</span>带上合适的出发设置</legend><div class="field-row"><div><label for="place">今天的场景</label><select name="place" id="place" value={game.preferences.place} disabled={trial}><option value="both">室内外都可以</option><option value="indoor">以室内为主</option><option value="outdoor">以户外为主</option></select></div><div><label for="budget">任务购物预算（元）</label><input id="budget" name="budget" type="number" inputmode="decimal" min="0" max="10000" step="0.01" value={game.preferences.budget} required disabled={trial}></div></div><p class="help">填0只抽零消费任务。不包含交通和日常餐费。</p><label class="score-choice"><input name="scoring" type="checkbox" checked={game.preferences.scoring} disabled={trial}><span><strong>{trial?'试玩不计分':'开启计分与奖励'}</strong><small>不计分也可以玩全部卡片，按自己的节奏完成。</small></span></label><button type="button" class="btn text" aria-expanded={rewardsOpen} aria-controls="setup-rewards" onclick={()=>rewardsOpen=!rewardsOpen}>看看我们的奖励</button><div id="setup-rewards" hidden={!rewardsOpen}><p class="help">按从小到大填写，出发时一起保存。留空使用默认奖励；进行中的旅程保留原奖励。</p>{#each game.preferences.rewards as reward,i}<label for={`setup-reward-${i}`}>第{i+1}档奖励</label><input id={`setup-reward-${i}`} name={`reward${i}`} value={reward} maxlength="80">{/each}</div></fieldset>
  </div>
  <aside class="departure-summary" aria-label="出发清单"><p class="eyebrow">这一程 / YOUR PLAN</p><div class="summary-postage"><PostageStamp variant={trial?0:choice.journeyTheme==='observe'?4:choice.journeyTheme==='duo'?5:3}/></div><h2 data-plan-mode>{modeCopy[choice.mode].title}</h2><p class="plan-theme" data-plan-theme>{trial?'三卡小冒险':theme.name}</p><dl><div><dt>同行者</dt><dd>我们两个人</dd></div><div><dt>时间</dt><dd>{modeCopy[choice.mode].time}</dd></div><div><dt>场景</dt><dd>{trial?'室内外都可以':choice.place==='indoor'?'以室内为主':choice.place==='outdoor'?'以户外为主':'室内外都可以'}</dd></div><div><dt>任务预算</dt><dd data-plan-budget>{trial||!choice.budget?'无需花费':`¥${choice.budget} 内`}</dd></div><div><dt>玩法</dt><dd>{!trial&&choice.scoring?'计分 · 解锁奖励':'轻松玩 · 不计分'}</dd></div></dl><div class="plan-stops" aria-label="计划任务">{#each sequence as type,i}<span class={type}>{i+1}<small>{taskNames[type]}</small></span>{:else}<p>自由抽取，随时收尾。</p>{/each}</div><div class="departure-action"><span class="mobile-plan"><strong>{modeCopy[choice.mode].title}{trial?'':` · ${theme.name}`}</strong><small>{modeCopy[choice.mode].time} · {trial||!choice.budget?'零消费':`¥${choice.budget} 内`}</small></span><button class="btn block" type="submit">出发</button></div><p class="help">途中随时暂停、换卡或结束。<br>共同完成的小事，会留在纪念册里。</p></aside>
 </form>{/if}
</div>

<style>
.theme-example{margin-top:16px;padding:14px;border:1px dashed var(--line);background:var(--paper)}.theme-example h3{font-size:.9375rem;margin:8px 0}.theme-example p{font-size:.8125rem;line-height:1.6;margin:6px 0}#setup-rewards{padding:12px 0 0}#setup-rewards[hidden]{display:none}

.expedition-setup{max-width:1000px}.expedition-intro{display:grid;grid-template-columns:1fr 1.45fr;gap:32px;align-items:center;margin:6px 0 32px;padding:0 0 28px;border-bottom:1px solid var(--line)}.expedition-intro h2{font-size:clamp(1.6rem,3vw,2.2rem);line-height:1.4;margin:8px 0 12px}.expedition-intro p:last-child{font-size:.875rem;color:var(--muted);margin:0}.expedition-intro .eyebrow{margin:0;font-size:10px}
.expedition-form{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:28px;align-items:start}.expedition-controls{min-width:0}.setup-section{margin:0 0 24px;padding:18px 20px 20px;background:var(--white);border:1px solid var(--line);border-radius:5px;min-width:0}.setup-section legend{font-size:1.05rem;font-weight:700;display:flex;align-items:center;gap:10px;padding:0 6px}.step-number{background:var(--ink);color:#ffe3a1;font:12px ui-monospace,monospace;padding:6px 8px;border-radius:2px}.section-help{font-size:12px;color:var(--muted);margin:0 0 18px}.trip-modes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.trip-mode{position:relative;display:flex;flex-direction:column;text-align:left;margin:0;min-height:142px;padding:14px;border:2px solid #c8d3ce;border-radius:4px;background:var(--paper);cursor:pointer}.trip-mode input{position:absolute;top:14px;right:12px;width:18px;height:18px;margin:0;accent-color:var(--green);padding:0}.mode-icon{font:25px/1.2 ui-monospace,monospace;color:var(--green);margin-bottom:12px}.trip-mode strong{font-size:15px;line-height:1.4;margin-bottom:5px}.mode-time{font-size:12px;color:#36556a}.mode-note{font-size:11px;color:var(--muted);font-weight:400;margin-top:7px}.trip-mode:has(input:checked){border-color:var(--green);background:#e8f1e4;box-shadow:3px 3px var(--green)}.trip-mode:focus-within,.theme-route:focus-within{outline:2px solid var(--accent);outline-offset:3px}
.theme-routes{display:grid;gap:12px}.theme-route{position:relative;display:flex;align-items:center;gap:14px;border:2px solid var(--line);border-radius:4px;padding:12px;margin:0;cursor:pointer}.theme-route>input{position:absolute;width:18px;height:18px;top:10px;right:10px;padding:0;margin:0;accent-color:var(--green)}.route-stamp{width:72px;flex:none;transform:rotate(-4deg)}.theme-route>span:not(.route-check){min-width:0;padding-right:15px}.theme-route strong{font-size:15px}.route-description{display:block;font-size:12px;font-weight:400;line-height:1.8;color:var(--muted);margin-top:5px}.route-check{display:none}.theme-route:has(input:checked){border-color:var(--green);background:#eef4e8;box-shadow:3px 3px #17354d18}.trial-themes{opacity:.6}.trial-themes .theme-route{cursor:default}.setup-section>.help{font-size:12px;line-height:1.8}.setup-section input,.setup-section select{border-radius:4px}.setup-section label[for]{font-size:13px}.score-choice{display:flex;gap:12px;align-items:center;padding:14px 0;margin:14px 0 0;border-top:1px dashed var(--line)}.score-choice input{width:20px;height:20px;flex:none;accent-color:var(--green)}.score-choice strong{font-size:14px}.score-choice small{display:block;font-size:12px;color:var(--muted);font-weight:400;margin-top:5px}.setup-section :global(.btn.text){font-size:12px;padding-left:0}
.departure-summary{position:sticky;top:24px;padding:24px;background:#edf3e8;border:2px solid #19394f;box-shadow:4px 4px #17354d18;border-radius:4px;text-align:center}.departure-summary .eyebrow{font:10px ui-monospace,monospace;margin-bottom:22px}.summary-postage{width:112px;margin:0 auto 20px;transform:rotate(5deg)}.departure-summary h2{font-size:1.35rem;margin:0 0 5px}.plan-theme{font-size:13px;color:var(--green);margin-bottom:18px}.departure-summary dl{margin:0;border-top:1px dashed #92b7a1;padding-top:10px}.departure-summary dl>div{display:flex;justify-content:space-between;gap:12px;font-size:12px;padding:7px 0}.departure-summary dt{color:var(--muted)}.departure-summary dd{margin:0;font-weight:600;text-align:right}.plan-stops{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin:20px 0 24px}.plan-stops>span{display:flex;flex-direction:column;align-items:center;font:12px ui-monospace,monospace;gap:5px;width:38px;padding-top:7px;border-top:3px solid var(--green)}.plan-stops>span.talk{border-color:var(--blue)}.plan-stops>span.event{border-color:#a65530}.plan-stops small{font:10px 'Microsoft YaHei',sans-serif}.plan-stops p{font-size:12px;margin:0}.departure-summary>.help{font-size:11px;line-height:1.9;margin-top:18px}.resume-adventure{max-width:620px;margin:0 auto}.resume-adventure>.panel{margin-top:24px}
.mobile-plan{display:none}
@media(max-width:800px){.expedition-setup{padding-bottom:85px}.expedition-intro{grid-template-columns:1fr;gap:22px;margin-bottom:28px}.expedition-intro h2 br{display:none}.expedition-intro h2{font-size:1.65rem}.expedition-form{grid-template-columns:1fr;gap:0}.departure-summary{position:static;margin:0 3px}.summary-postage{width:90px}.departure-summary dl{max-width:400px;margin:auto}.setup-section{padding:16px}.trip-mode{padding:12px;min-height:140px}.trip-mode strong{font-size:14px}.route-stamp{width:60px}.theme-route{gap:12px}.theme-route strong{font-size:14px}.field-row{grid-template-columns:1fr}.departure-summary>.help{font-size:12px}.departure-action{position:fixed;z-index:9;bottom:calc(82px + env(safe-area-inset-bottom));left:12px;right:12px;max-width:560px;margin:auto;padding:10px 12px;display:grid;grid-template-columns:minmax(0,1fr) 110px;align-items:center;gap:10px;background:#fff8e9f5;border:2px solid #19394f;border-radius:5px;box-shadow:3px 3px #17354d22;backdrop-filter:blur(10px)}.mobile-plan{display:block;text-align:left;min-width:0}.mobile-plan strong{display:block;font-size:13px}.mobile-plan small{display:block;color:var(--muted);font-size:11px;font-weight:400;margin-top:4px}.departure-action .btn{font-size:14px;padding:10px}}
@media(min-width:801px) and (max-height:850px){.departure-summary{position:static}}
</style>
